head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gIndex;
scwin.gIsurCd;
scwin.gComAbbrv;
scwin.gSchDate;
scwin.gDutyYn = js_duty;
scwin.gJobTitle = js_jobtitl;
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.vScrenID = "ULDSTF37400.xml";
scwin.gISUR_CD;
scwin.gCOM_NM;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

//페이지 로딩 시 필요한 변수 초기화
scwin.fn_SetCode = function() {
    dts_EMP_NO.DataID = "/CodeAction.do?method=getEmpNoDepCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + scwin.gDepCd;
    dts_EMP_NO.Reset();
    dts_DEP_CD.DataID = "/CodeAction.do?method=getDepUpCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + scwin.gDepCd;
    dts_DEP_CD.Reset();


    //조회일자 오늘로 셋팅
    /*
    	2020.09.03 KBoY 
    	상장일은 무조건 3년전 7월1일 부터 당해 6월 30일까지 인데, 나머지(불성실, 관리종목 등)은 3년전 7월1일 부터 조회일까지로 두개가 불일치하여 
    	혼돈의 소지가 있어 날짜를 수정할 수 없게 바꾸고, 조회일자도 7월 1일로 고정되게 만든다.(현업 요청)
    */
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (vCurDate < (vCurDate.substr(0, 4) + '0601')) edt_SchDate.setValue((vCurDate.substr(0, 4) - 1) + '0701');

    else edt_SchDate.setValue(vCurDate.substr(0, 4) + '0701');

    //setObjectValue(rdo_EXT_ID, '1');


    if (scwin.gJobTitle == '09') {
        $c.stf.showObj(pnl_batch, true);
    } else {
        $c.stf.showObj(pnl_batch, false);
    }
};




// 조회
scwin.fn_Search = function() {
    var vISUR_CD = $c.stf.getObjectValue(txb_isur_cd);
    var vSCH_DD = $c.stf.getObjectValue(edt_SchDate);
    var vDEP_CD = $c.stf.getObjectValue(cmb_DEP_CD);
    var vEMP_NO = $c.stf.getObjectValue(cmb_EMP_NO);
    //		var vEXT_ID = getObjectValue(rdo_EXT_ID);

    var url;
    url = "/ByPass.do?method=listByPassKosdaq";
    url += "&ISUR_CD=" + vISUR_CD;
    url += "&SCH_DD=" + vSCH_DD;
    url += "&DEP_CD=" + vDEP_CD;
    url += "&EMP_NO=" + vEMP_NO;
    //		url += "&EXT_ID=" + vEXT_ID;		
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Grid.DataID = encodeURI(url);
    dts_Grid.Reset();
    $c.cm.ShowWin(grd_Grid);
};



//일괄 지정/해제 수행
//2020.09.08 KBoY
scwin.doBatch4ByPass = function() {
    var dtec_dd = dts_Grid.getCellData(1, "DTEC_DD");
    var msg = "금일 기 신청한 일괄신청 지정/해제 건은 모두 삭제됩니다.\r\n계속 진행하시겠습니까? ";
    if (confirm(msg)) {
        if (scwin.setCommonInfo()) {
            tr_batch.Action = "/ByPass.do?method=doBatch4ByPass&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
            tr_batch.KeyName = "toinb_dataid4";
            tr_batch.KeyValue = "JSP(I:pInput=dts_Grid)";
            tr_batch.Post();
        } else {
            $c.win.alert('지정일 세팅중 오류 발생');
        }
    }
};




//지정일&처리자 세팅. 전체에 넣어주면 전체 row가 업데이트 된걸로 인식함. 그래서 체크된 row만 넣어줌
//2020.09.08 KBoY
scwin.setCommonInfo = function() {
    var assignDD = edt_assignDD.getValue();
    var chkVal = 0;
    for (i = 1; i <= dts_Grid.getTotalRow(); i++) {
        chkVal = dts_Grid.getCellData(i, "CHK_FLAG");
        if (chkVal == 1) {
            dts_Grid.setCellData(i, "assign_dd", assignDD);
            dts_Grid.setCellData(i, "reg_id", scwin.gEmpNo);
        }
    }
    return true;
};
scwin.isChecked = function() {
    var cnt = 0;
    var chkVal = 0;
    for (i = 1; i <= dts_Grid.getTotalRow(); i++) {
        chkVal = dts_Grid.getCellData(i, "CHK_FLAG");
        if (chkVal == 1) cnt++;
    }
    if (cnt == 0) return false;

    else return true;
};
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.dts_Grid_OnLoadError = function() {
    $c.stf.alert_error(dts_Grid);
};
scwin.cmb_DEP_CD_OnSelChange = function() {
    scwin.gDepCd = $c.stf.getObjectValue(cmb_DEP_CD); //;.ValueOfIndex("VALUE", cmb_DEP_CD.Index);

    dts_EMP_NO.UseFilter = true;
    dts_EMP_NO.Filter();
};
scwin.dts_EMP_NO_OnFilter = function(row) {
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_EMP_NO.getCellData(row, "dep_cd") == scwin.gDepCd ||
            dts_EMP_NO.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.grd_Grid_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    scwin.gIsurCd = dts_Grid.getCellData(eval(row), "ISUR_CD");
    scwin.gComAbbrv = dts_Grid.getCellData(eval(row), "COM_ABBRV");
    scwin.gSchDate = edt_SchDate.getValue();
    gDtecDate = dts_Grid.getCellData(eval(row), "DTEC_DD");
    if (colid == "COM_ABBRV") {
        // 회사정보 
        $c.stf.fn_PopupCorpInfo();
    } else if (colid == "EXCNT_DISCLS_CORP_YN") {
        // 공시우수
        var url = "/dsclmgt/ULDSTF37301.gfm";
        url += "?POPUPMODE";
        var winTitle = "우수공시법인현황";
        await $c.frame.CreateFrame("ULDSTF37301", url, winTitle, 100, 100, 830, 510, "window", 0, 0, true);
    } else if (colid == "NFAITHDISCLS_CORP_YN") {
        // 불성실공시 
        var url = "/dsclmgt/ULDSTF37401.gfm";
        url += "?POPUPMODE";
        var winTitle = "불성실공시법인 현황(최근3년)";
        await $c.frame.CreateFrame("ULDSTF37401", url, winTitle, 50, 50, 830, 520, "window", 0, 0, true);
    } else if (colid == "DISCLS_EDU_COMPLT_COND_YN") {
        //공시교육
        var url = "/dsclmgt/ULDSTF37403.gfm";
        url += "?POPUPMODE";
        var winTitle = "공시책임자 및 공시담당자 교육이수 현황(최근2년)";
        await $c.frame.CreateFrame("ULDSTF37403", url, winTitle, 50, 50, 830, 520, "window", 0, 0, true);
    } else if (colid == "ADMISU_YN") {
        // 관리종목
        var url = "/dsclmgt/ULDSTF37404.gfm";
        url += "?POPUPMODE";
        var winTitle = "관리종목 지정 현황(최근3년)";
        await $c.frame.CreateFrame("ULDSTF37404", url, winTitle, 50, 50, 830, 520, "window", 0, 0, true);
    } else if (colid == "INVSTCAUTN_REMND_ISU_YN") {
        // 투자주의환기종목
        var url = "/dsclmgt/ULDSTF37405.gfm";
        url += "?POPUPMODE";
        var winTitle = "투자주의 환기종목 지정 현황(최근3년)";
        await $c.frame.CreateFrame("ULDSTF37405", url, winTitle, 50, 50, 830, 520, "window", 0, 0, true);
    } else if (colid == "AUDT_OPIN_OPT_YN") {
        // 감사의견 
        var url = "/dsclmgt/ULDSTF37402.gfm";
        url += "?POPUPMODE";
        var winTitle = "최근 사업연도 감사의견 현황(최근1년)";
        await $c.frame.CreateFrame("ULDSTF37402", url, winTitle, 50, 50, 830, 520, "window", 0, 0, true);
    }
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    $c.data.downloadGridViewExcel(grd_Grid, "면제대상현황", "", "8");
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.gform_onload = function() {
    scwin.fn_SetCode();
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    scwin.fn_Search();
};
scwin.grd_Grid_OnClick = function(row, colid) {
    var chkVal = dts_Grid.getCellData(eval(row), "CHK_FLAG");
};
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_assignDD);
};
scwin.btn_assignAll_onclick = function() {
    var selectedApplDate = "";
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    selectedApplDate = edt_assignDD.getValue();
    if (vCurDate >= selectedApplDate) {
        $c.win.alert("오늘 날짜 이후만 가능");
        return false;
    } else {
        if (scwin.isChecked()) {
            var msg = "체크된 항목을 반영일 기준으로 일괄 지정/해제 처리 하시겠습니까?";
            if (confirm(msg)) {
                scwin.doBatch4ByPass();
            }
        } else {
            $c.win.alert('일괄 지정/해제를 위해 체크된 항목이 없습니다.');
        }
    }
};
scwin.btn_selAll_onclick = function() {
    var sameYN = "";
    var msg = "기존 체크 여부를 무시하고, 상장원부 일치여부가 'N'인것만 체크합니다.\r\n계속 진행 하시겠습니까?";
    if (confirm(msg)) {
        for (var i = 1; i <= dts_Grid.getTotalRow(); i++) {
            sameYN = dts_Grid.getCellData(eval(i), "LIST_ORG_YN");
            if (sameYN == "N") {
                dts_Grid.setCellData(eval(i, 1), "CHK_FLAG");
            } else {
                dts_Grid.setCellData(eval(i, 0), "CHK_FLAG");
            }
        }
    }
};
scwin.tr_batch_OnSuccess = function() {
    $c.win.alert('일괄지정 처리가 완료되었습니다');
    dts_Grid.Reset();
};
